mapper.select:
select * from MST_INT_RATE_INFO


        AND EFF_DATE >= STR_TO_DATE(#{startDate},'%Y-%m-%d')


        AND STR_TO_DATE(#{endDate},'%Y-%m-%d') >= EFF_DATE


        AND INT_RATE_TYPE = #{intRateType}


        AND INT_RATE_ID = #{intRateId}

select * from (
select t.INT_RATE from MST_INT_RATE_INFO t


        AND STR_TO_DATE(#{rateEmptyDay},'%Y-%m-%d') >= t.EFF_DATE


        AND t.INT_RATE_TYPE = #{intRateType}


        AND t.INT_RATE_ID = #{intRateId}

    AND t.INT_RATE is not null

order by t.EFF_DATE DESC
)
where LIMIT = 1
